import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

// Load credentials generated by seed script
const users = new SharedArray('users', function () {
    return JSON.parse(open('./loadtest_users.json'));
});

export const options = {
    stages: [
        { duration: '1m', target: 50 },  // Ramp-up: Tăng dần lên 50 users trong 1 phút
        { duration: '2m', target: 100 }, // Steady: Duy trì 100 users trong 2 phút
        { duration: '1m', target: 0 },   // Ramp-down: Giảm về 0 trong 1 phút
    ],
    thresholds: {
        http_req_duration: ['p(95)<1500'], // 95% requests phải dưới 1.5 giây (1500ms)
        http_req_failed: ['rate<0.01'],   // Tỷ lệ lỗi dưới 1%
    },
};

export default function () {
    const BASE_URL = __ENV.BASE_URL || 'http://localhost:3000';
    
    // Pick a user based on VU ID
    const userIndex = (__VU - 1) % users.length;
    const user = users[userIndex];
    
    // 1. Lấy CSRF token từ Next-Auth
    const csrfRes = http.get(`${BASE_URL}/api/auth/csrf`);
    const csrfToken = csrfRes.json().csrfToken;
    
    // 2. Đăng nhập qua Credentials Provider
    const loginPayload = {
        email: user.email,
        password: user.password,
        csrfToken: csrfToken,
        callbackUrl: '/',
        json: 'true'
    };
    
    const loginRes = http.post(`${BASE_URL}/api/auth/callback/credentials`, loginPayload);
    
    const isLoginOk = check(loginRes, {
        'login status is 200': (r) => r.status === 200,
        'login body has url': (r) => r.body.includes('url'),
    });
    
    if (isLoginOk) {
        // 3. Đọc Dashboard API
        const dashboardRes = http.get(`${BASE_URL}/api/student/dashboard`);
        check(dashboardRes, {
            'dashboard loaded (200)': (r) => r.status === 200,
            'dashboard contains profile': (r) => r.body.includes('profile') || r.body.includes('student'),
        });

        // 4. Đọc Checklist API
        const checklistRes = http.get(`${BASE_URL}/api/student/checklist`);
        check(checklistRes, {
            'checklist loaded (200)': (r) => r.status === 200,
        });
    } else {
        console.error(`❌ VU ${__VU}: Login failed for ${user.email}`);
    }
    
    sleep(2); // Đợi 2 giây trước khi thực hiện lượt tiếp theo
}
